_LINK_ZONES = {
    "US/Pacific": "America/Los_Angeles",
    "US/Eastern": "America/New_York",
    "US/Central": "America/Chicago",
    "Asia/Calcutta": "Asia/Kolkata",
    "Asia/Saigon": "Asia/Ho_Chi_Minh",
    "Europe/Kiev": "Europe/Kyiv",
    "America/Buenos_Aires": "America/Argentina/Buenos_Aires",
    "Brazil/East": "America/Sao_Paulo",
    "UTC": "Etc/UTC",
    "GMT": "Etc/UTC",
}

_OFFSET_RE = re.compile(r"^(?:UTC|GMT)?\s*([+-\u2212])(\d{1,2})(?::?(\d{2}))?$", re.IGNORECASE)


def _zone(tz: str) -> str:
    """The canonical IANA zone id Meridale expects for a stored zone name or fixed offset."""
    tz = tz.strip()
    if tz in _LINK_ZONES:
        return _LINK_ZONES[tz]
    m = _OFFSET_RE.match(tz)
    if m:
        sign, hours, minutes = m.group(1), int(m.group(2)), int(m.group(3) or 0)
        if minutes:
            raise ValueError(f"no whole-hour zone for offset {tz!r}")
        if hours == 0:
            return "Etc/UTC"
        # POSIX convention: the sign is inverted.
        return f"Etc/GMT{'-' if sign == '+' else '+'}{hours}"
    return tz


_SUPPORTED_LOCALES = ("en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP")


def _locale(posix: str) -> str:
    """The BCP 47 locale Meridale supports that best matches a POSIX locale name."""
    name = re.split(r"[.@]", posix.strip(), maxsplit=1)[0]
    parts = [p for p in re.split(r"[_-]", name) if p]
    if not parts:
        return "en-US"
    lang = parts[0].lower()
    region = next((p.upper() for p in parts[1:] if len(p) == 2 and p.isalpha()), None)
    if region and f"{lang}-{region}" in _SUPPORTED_LOCALES:
        return f"{lang}-{region}"
    if lang in _SUPPORTED_LOCALES:
        return lang
    return "en-US"


_ZERO_DIGITS = {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}
_THREE_DIGITS = {"BHD", "JOD", "KWD", "OMR", "TND"}


def _digits(currency: str) -> int:
    if currency in _ZERO_DIGITS:
        return 0
    if currency in _THREE_DIGITS:
        return 3
    return 2


def _amount(value: str, digits: int) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_UP) + 0


# locale -> (decimal separator, group separator, code position)
_STYLES = {
    "en-US": (".", ",", "before"),
    "en-GB": (".", ",", "before"),
    "ja-JP": (".", ",", "before"),
    "en-IN": (".", ",", "before"),
    "pt-BR": (",", ".", "before"),
    "de-DE": (",", ".", "after"),
    "es": (",", ".", "after"),
    "de-CH": (".", "\u2019", "after"),
    "fr-FR": (",", "\u202f", "after"),
}


def _group(integer: str, locale: str, sep: str) -> str:
    if locale == "es" and len(integer) == 4:
        return integer
    if locale == "en-IN":
        if len(integer) <= 3:
            return integer
        head, tail = integer[:-3], integer[-3:]
        pieces = []
        while len(head) > 2:
            pieces.insert(0, head[-2:])
            head = head[:-2]
        if head:
            pieces.insert(0, head)
        return sep.join(pieces + [tail])
    pieces = []
    while len(integer) > 3:
        pieces.insert(0, integer[-3:])
        integer = integer[:-3]
    pieces.insert(0, integer)
    return sep.join(pieces)


def _text(value: Decimal, currency: str, locale: str, digits: int) -> str:
    decimal_sep, group_sep, position = _STYLES[locale]
    negative = value < 0
    whole, _, frac = f"{abs(value):.{digits}f}".partition(".")
    number = _group(whole, locale, group_sep) + (decimal_sep + frac if digits else "")
    if negative:
        number = "-" + number
    nbsp = "\u00a0"
    return f"{currency}{nbsp}{number}" if position == "before" else f"{number}{nbsp}{currency}"
